module tb_TopModule;
    reg [3:0] x;
    reg [3:0] y;
    wire [4:0] sum;

    TopModule dut (
        .x(x),
        .y(y),
        .sum(sum)
    );

    initial begin
        integer i, j;
        reg [4:0] expected;
        integer errors;
        errors = 0;

        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                x = i[3:0];
                y = j[3:0];
                #1;
                expected = i + j;
                if (sum !== expected) begin
                    $display("FAIL: x=%0d, y=%0d -> got sum=%0d (0x%h), expected=%0d (0x%h)", 
                             i, j, sum, sum, expected, expected);
                    errors = errors + 1;
                end
            end
        end

        if (errors == 0) begin
            $display("SELFTEST PASS");
        end else begin
            $display("SELFTEST FAIL: %0d errors found", errors);
        end
        $finish;
    end
endmodule
